<script setup>
import {ref} from 'vue';
const props=defineProps({eventId:Number,registration:Object,canManage:Boolean});const emit=defineEmits(['updated']);const open=ref(false),method=ref(''),date=ref(new Date().toLocaleDateString('sv-SE',{timeZone:'America/Bahia'})),busy=ref(false),error=ref('');
async function pay(){busy.value=true;error.value='';try{await window.axios.post('/api/events/'+props.eventId+'/registrations/'+props.registration.id+'/payment',{method:method.value,paid_at:date.value});open.value=false;emit('updated',props.eventId);}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'Não foi possível registrar.';}finally{busy.value=false;}}
</script>
<template><section v-if="registration.charge" class="event-payment"><p><strong>{{Number(registration.charge.valor).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}}</strong> · {{({pago:'Pago',pendente:'Pagamento pendente',atrasado:'Pagamento em atraso',cancelado:'Cobrança cancelada'})[registration.charge.status]}}</p><p v-if="registration.charge.refund_review_required" role="status">Evento cancelado: devolução a conferir com o participante. Recebimento preservado no histórico.</p><template v-if="canManage&&['pendente','atrasado'].includes(registration.charge.status)"><button v-if="!open" class="btn-secondary" @click="open=true">Registrar pagamento</button><form v-else @submit.prevent="pay"><label>Forma de pagamento<select v-model="method" required><option value="" disabled>Escolha</option><option v-for="m in ['PIX','Crédito','Débito','Dinheiro','Transferência','Boleto']" :key="m">{{m}}</option></select></label><label>Recebido em<input v-model="date" type="date" required /></label><ActionFeedback :message="error" type="error" /><button class="btn-primary" :disabled="busy">Confirmar recebimento</button><button type="button" class="btn-secondary" :disabled="busy" @click="open=false">Voltar</button></form></template></section></template>
<style scoped>.event-payment{padding:12px 0}.event-payment label{display:grid;gap:8px;margin:12px 0;font-size:14px}.event-payment input,.event-payment select{width:100%;padding:12px;border:1px solid var(--wn-line);border-radius:10px;font-size:16px}.event-payment button{margin:8px 8px 8px 0;min-height:44px}</style>
